node -e 'const fs = require("node:fs");
// USMR 14.72 (site-2m1.72): never acquire an edit-hook executable.
function formatFiles(input, files) {
  const path = require("node:path");
  const cp = require("node:child_process");
  const sessionCwd = path.resolve(input.cwd || process.cwd());
  let root = sessionCwd;
  // Stop at the nearest project marker; never borrow an ancestor install.
  while (!fs.existsSync(path.join(root, "node_modules", ".bin", "prettier")) && !fs.existsSync(path.join(root, "package.json"))) {
    const parent = path.dirname(root);
    if (parent === root) break;
    root = parent;
  }
  const prettier = path.join(root, "node_modules", ".bin", "prettier");
  if (!fs.existsSync(prettier)) {
    console.error("Skipping formatting: local node_modules/.bin/prettier is absent; install locked dependencies first.");
    return;
  }
  const targets = [...new Set(files.map(f => path.resolve(sessionCwd, f)))].filter(f => fs.existsSync(f));
  if (targets.length === 0) return;
  const result = cp.spawnSync(prettier, ["--write", "--ignore-unknown", "--", ...targets], { cwd: root, stdio: ["ignore", "pipe", "pipe"], encoding: "utf8" });
  if (result.stdout) process.stderr.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  if (result.error) {
    console.error("Local Prettier could not run: " + result.error.message);
    process.exit(1);
  }
  if (result.signal) {
    console.error("Local Prettier terminated by " + result.signal);
    process.exit(1);
  }
  process.exit(result.status === 0 ? 0 : 1);
}
try {
  const input = JSON.parse(fs.readFileSync(0, "utf8"));
  const file = input?.tool_input?.file_path;
  if (typeof file !== "string" || !file.trim() || /[\0\r\n]/.test(file)) throw new Error();
  if (file.toLowerCase().includes(".env")) {
    console.error("Skipping formatting: environment files are protected.");
  } else {
    formatFiles(input, [file]);
  }
} catch {
  console.error("Formatting failed: malformed Claude edit input.");
  process.exit(1);
}'

